async function fetchYahooQuoteViaProxy(yahooSym) {
  const targetUrl = `https://query1.finance.yahoo.com/v8/finance/chart/${encodeURIComponent(yahooSym)}?interval=1d&range=5d`;
  const proxies = [
    `https://corsproxy.io/?${encodeURIComponent(targetUrl)}`,
    `https://api.allorigins.win/raw?url=${encodeURIComponent(targetUrl)}`,
    `https://api.codetabs.com/v1/proxy?quest=${encodeURIComponent(targetUrl)}`
  ];
  for (const url of proxies) {
    try {
      const controller = new AbortController();
      const tid = setTimeout(() => controller.abort(), 3500);
      const res = await fetch(url, { signal: controller.signal, cache: 'no-store' });
      clearTimeout(tid);
      if (!res.ok) continue;
      const json = await res.json();
      const result = json && json.chart && json.chart.result && json.chart.result[0];
      if (!result) continue;
      const meta = result.meta || {};
      const divScale = meta.currency === 'GBp' ? 100.0 : 1.0;
      const quote = result.indicators && result.indicators.quote && result.indicators.quote[0];
      const closes = (quote && quote.close ? quote.close : []).filter(v => v !== null && v !== undefined).map(v => v / divScale);
      if (closes.length >= 2) {
        const curPrice = (meta.regularMarketPrice ? (meta.regularMarketPrice / divScale) : closes[closes.length - 1]);
        const prevClose = closes[closes.length - 2];
        const firstClose = closes[0];
        const dayChangePct = (meta.regularMarketChangePercent !== undefined && meta.regularMarketChangePercent !== null)
          ? parseFloat(Number(meta.regularMarketChangePercent).toFixed(2))
          : parseFloat((((curPrice - prevClose) / prevClose) * 100).toFixed(2));
        const roc5d = parseFloat((((curPrice - firstClose) / firstClose) * 100).toFixed(2));
        return { curPrice: parseFloat(Number(curPrice).toFixed(2)), dayChangePct, roc5d, closes: closes.map(c => parseFloat(c.toFixed(2))) };
      }
    } catch (_) {
      // Prova il proxy successivo
    }
  }
  return null;
}

async function refreshLiveQuotesClientSide(data) {
  if (!data || (!data.eu && !data.usa && !data.it)) return data;
  const allItems = [
    ...(data.eu || []).slice(0, 15).map(item => ({ item, market: 'eu' })),
    ...(data.it || []).slice(0, 15).map(item => ({ item, market: 'it' })),
    ...(data.usa || []).slice(0, 15).map(item => ({ item, market: 'usa' })),
    ...(data.top || []).slice(0, 15).map(item => ({ item, market: 'top' }))
  ];

  await Promise.allSettled(allItems.map(async ({ item }) => {
    const ySym = YAHOO_SYMBOL_MAP[item.ticker] || item.ticker;
    const live = await fetchYahooQuoteViaProxy(ySym);
    if (live && live.curPrice > 0) {
      const oldDayChg = item.dayChangePct || 0;
      const ratio = live.curPrice / (item.currentPrice || live.curPrice);
      item.currentPrice = live.curPrice;
      item.dayChangePct = live.dayChangePct;
      item.roc5d = live.roc5d;

      // Ricalcola dinamicamente lo score se la variazione intraday è cambiata (es. apertura Wall Street)
      const deltaChg = live.dayChangePct - oldDayChg;
      if (Math.abs(deltaChg) >= 0.15) {
        let baseRaw = item.rawScore || item.score || 88;
        baseRaw += deltaChg * 2.2;
        if (live.dayChangePct < -0.35 && oldDayChg >= 0) {
          baseRaw -= Math.min(8.5, Math.abs(live.dayChangePct) * 3.8);
        }
        item.rawScore = parseFloat(baseRaw.toFixed(1));
        const scaled = item.rawScore > 85.0 ? 85.0 + (item.rawScore - 85.0) * 0.65 : item.rawScore;
        item.score = Math.max(48, Math.min(97, Math.round(scaled)));
        item.strength = item.score >= 86 ? 'Molto Alta' : (item.score >= 78 ? 'Alta' : 'Moderata');
      }

      if (item.targetPct && item.stopPct) {
        item.targetPrice = parseFloat((live.curPrice * (1 + item.targetPct / 100)).toFixed(2));
        item.stopLoss = parseFloat((live.curPrice * (1 - item.stopPct / 100)).toFixed(2));
      } else {
        item.targetPrice = parseFloat((item.targetPrice * ratio).toFixed(2));
        item.stopLoss = parseFloat((item.stopLoss * ratio).toFixed(2));
      }
      if (item.avg52w && item.avg52w > 0) {
        const diff52 = parseFloat((((live.curPrice - item.avg52w) / item.avg52w) * 100).toFixed(1));
        item.diff52wPct = diff52;
        if (diff52 < -10.0) {
          item.border52w = 'green';
          item.status52w = `Sotto Media 52W (${diff52}%)`;
        } else if (diff52 <= 10.0) {
          item.border52w = 'orange';
          item.status52w = `Nel Range ±10% (${diff52 >= 0 ? '+' : ''}${diff52}%)`;
        } else {
          item.border52w = 'red';
          item.status52w = `Sopra Media 52W (+${diff52}%)`;
        }
      }
      if (item.chartData && item.chartData['5D'] && live.closes.length >= 2) {
        item.chartData['5D'].values = live.closes.slice(-5);
      }
    }
  }));

  // Riordina entrambi i listini in base allo score aggiornato in tempo reale
  data.eu.sort((a, b) => (b.rawScore || b.score) - (a.rawScore || a.score));
  data.usa.sort((a, b) => (b.rawScore || b.score) - (a.rawScore || a.score));

  return data;
}

async function triggerFullMarketRefresh(source = 'button') {
  if (state.isRefreshing) return;
  state.isRefreshing = true;

  const ptrBar = document.getElementById('pullToRefreshBar');
  const ptrIcon = document.getElementById('ptrIcon');
  const ptrText = document.getElementById('ptrText');

  if (source !== 'market_switch' && ptrBar && ptrIcon && ptrText) {
    ptrBar.classList.remove('pulling', 'ready');
    ptrBar.classList.add('refreshing');
    ptrIcon.innerHTML = `<i class="fa-solid fa-spinner fa-spin"></i>`;
    ptrText.textContent = `Sincronizzazione prezzi live in corso...`;
  }

  if (elements.refreshBtn) {
    elements.refreshBtn.innerHTML = `<i class="fa-solid fa-spinner fa-spin"></i> Scansione Prezzi...`;
    elements.refreshBtn.disabled = true;
  }

  let updated = false;
  let isCloudOrLocal = false;

  // 1. Chiamata in tempo reale al backend Google Cloud Run (o server locale)
  try {
    const isLocal = window.location.hostname === 'localhost' || window.location.hostname === '127.0.0.1';
    const refreshUrl = isLocal ? '/api/refresh' : `${GOOGLE_CLOUD_API}/api/refresh`;
    const res = await fetch(refreshUrl, { cache: 'no-store' });
    if (res.ok) {
      const data = await res.json();
      if (data && (data.eu || data.it || data.usa || data.top)) {
        applyRealMarketData(data);
        updated = true;
        isCloudOrLocal = true;
        state.isLiveServerConnected = true;
        if (elements.liveFeedStatus) {
          elements.liveFeedStatus.innerHTML = `<i class="fa-solid fa-bolt text-emerald"></i> GOOGLE CLOUD LIVE ATTIVO`;
        }
      }
    }
  } catch (_) {
    // Fallback automatico su archivio cloud se offline
  }

  // 2. Se in modalità Web statica o fallback, scarica l'ultimo dataset reale bypassando la cache CDN
  if (!updated) {
    try {
      let baseData = null;
      try {
        const fRes = await fetch('market_data.json?t=' + Date.now(), { cache: 'no-store' });
        if (fRes.ok) {
          baseData = await fRes.json();
        }
      } catch (_) {}

      // Fallback immediato su CDN GitHub raw per evitare ritardi di cache del CDN Pages
      if (!baseData) {
        try {
          const rawRes = await fetch('https://raw.githubusercontent.com/cell84calcio/alphapulse/main/market_data.json?t=' + Date.now(), { cache: 'no-store' });
          if (rawRes.ok) {
            baseData = await rawRes.json();
          }
        } catch (_) {}
      }

      if (baseData) {
        applyRealMarketData(baseData);
        updated = true;
      } else {
        renderStocks();
      }
    } catch (e) {
      renderStocks();
    }
  }

  const timeLabel = (REAL_DATASET && REAL_DATASET.lastUpdated) ? REAL_DATASET.lastUpdated.split(' ')[1].slice(0, 5) : '';

  if (source !== 'market_switch' && ptrBar && ptrIcon && ptrText) {
    ptrIcon.innerHTML = `<i class="fa-solid fa-check text-emerald"></i>`;
    ptrText.textContent = isCloudOrLocal 
      ? `Prezzi Live Scansionati al Secondo (Google Cloud)!` 
      : `Dati Sincronizzati al Cloud (${timeLabel ? timeLabel + ' CET' : 'Live'})`;
  }
  if (elements.refreshBtn) {
    elements.refreshBtn.innerHTML = isCloudOrLocal 
      ? `<i class="fa-solid fa-bolt text-emerald"></i> Prezzi Live Aggiornati!` 
      : `<i class="fa-solid fa-check text-emerald"></i> Dati Allineati (${timeLabel || 'OK'})`;
  }

  setTimeout(() => {
    if (source !== 'market_switch' && ptrBar && ptrIcon && ptrText) {
      ptrBar.classList.remove('refreshing', 'ready', 'pulling');
      ptrBar.style.height = '0px';
      ptrBar.style.opacity = '0';
      ptrIcon.innerHTML = `<i class="fa-solid fa-arrow-down"></i>`;
      ptrText.textContent = `Trascina in basso per sincronizzare i mercati`;
    }
    if (elements.refreshBtn) {
      elements.refreshBtn.innerHTML = `<i class="fa-solid fa-rotate"></i> Aggiorna Dati`;
      elements.refreshBtn.disabled = false;
    }
    state.isRefreshing = false;
  }, 1400);
}

async function loadLiveData() {
  try {
    const isLocal = window.location.hostname === 'localhost' || window.location.hostname === '127.0.0.1';
    const dataUrl = isLocal ? '/api/market-data' : `${GOOGLE_CLOUD_API}/api/market-data`;
    const res = await fetch(dataUrl, { cache: 'no-store' });
    if (res.ok) {
      const data = await res.json();
      applyRealMarketData(data);
      state.isLiveServerConnected = true;
      if (elements.liveFeedStatus) {
        elements.liveFeedStatus.innerHTML = `<i class="fa-solid fa-bolt text-emerald"></i> GOOGLE CLOUD LIVE ATTIVO (Milano)`;
      }
      return;
    }
  } catch (e) {
    try {
      let data = null;
      try {
        const fRes = await fetch('market_data.json?t=' + Date.now(), { cache: 'no-store' });
        if (fRes.ok) {
          data = await fRes.json();
        }
      } catch (_) {}

      if (!data) {
        try {
          const rawRes = await fetch('https://raw.githubusercontent.com/cell84calcio/alphapulse/main/market_data.json?t=' + Date.now(), { cache: 'no-store' });
          if (rawRes.ok) {
            data = await rawRes.json();
          }
        } catch (_) {}
      }

      if (data) {
        applyRealMarketData(data);
      }
    } catch (err) {
      console.log('Utilizzo dataset reale incorporato.');
    }
  }
}

function applyRealMarketData(data) {
  if (data && (data.eu || data.it || data.usa || data.top)) {
    REAL_DATASET = data;
    MARKET_DATA = {
      eu: data.eu || [],
      it: data.it || [],
      usa: data.usa || [],
      top: data.top || []
    };
    if (data.performanceTrackRecord && elements.mWinRateDisplay) {
      elements.mWinRateDisplay.innerHTML = `${data.performanceTrackRecord.winRate} <span class="metric-status">Win Rate 5G</span>`;
      if (elements.mWinRateSubtext) {
        elements.mWinRateSubtext.innerHTML = `Gain medio: <strong>${data.performanceTrackRecord.avgGain}</strong> &bull; Segnali monitorati: ${data.performanceTrackRecord.totalSignals}`;
      }
    }
    formatDateDisplay();
    renderStocks();
    updateWatchlistUI();
  }
}

// ==========================================================================
// 6. FILTRAGGIO E ORDINAMENTO
// ==========================================================================

function filterAndSortList(rawList) {
  const currentList = rawList || [];
  const query = state.searchQuery.toLowerCase().trim();
  let filtered = currentList.filter(stock => {
    if (state.sectorFilter !== 'all' && stock.sector !== state.sectorFilter) {
      return false;
    }

    // Filtro Capitalizzazione > 10 Miliardi (se attivo)
    if (state.isCap10BActive) {
      const cap = Number(stock.marketCapRaw || 0);
      if (cap < 10.0) {
        return false;
      }
    }

    // Filtro Prezzo < -1% (Quotazione in ribasso > 1%) (se attivo)
    if (state.isDrop1PctActive) {
      const dayChg = Number(stock.dayChangePct !== undefined ? stock.dayChangePct : 0);
      if (dayChg >= -1.0) {
        return false;
      }
    }

    const divY = Number(stock.dividendYield || 0);
    const payout = Number(stock.payoutRatio !== undefined ? stock.payoutRatio : (divY > 0 ? 50 : 0));
    const isSustainable = stock.isPayoutSustainable !== undefined
      ? Boolean(stock.isPayoutSustainable)
      : (divY > 0 && payout > 0 && payout <= 75 && Number(stock.roc5d || 0) >= -8.0);
    const curP = Number(stock.currentPrice || 0);
    const avg52 = Number(stock.avg52w || curP);
    const isUnder52w = (curP < avg52) || (Number(stock.diff52wPct || 0) < 0);

    if (state.dividendPriceFilter === 'div4' && !(divY > 4.0 && isSustainable)) {
      return false;
    }
    if (state.dividendPriceFilter === 'under52w' && !isUnder52w) {
      return false;
    }
    if (state.dividendPriceFilter === 'combo' && !(divY > 4.0 && isSustainable && isUnder52w)) {
      return false;
    }

    if (query) {
      const matchTicker = (stock.ticker || '').toLowerCase().includes(query);
      const matchName = (stock.name || '').toLowerCase().includes(query);
      const matchSector = (stock.sector || '').toLowerCase().includes(query);
      const matchSummary = (stock.summary || '').toLowerCase().includes(query);
      if (!matchTicker && !matchName && !matchSector && !matchSummary) {
        return false;
      }
    }
    return true;
  });

  filtered.sort((a, b) => {
    let sortMode = state.sortBy;
    if (sortMode === 'score') {
      return (b.rawScore || b.score) - (a.rawScore || a.score);
    } else if (sortMode === 'cap') {
      return (b.marketCapRaw || 0) - (a.marketCapRaw || 0);
    } else if (sortMode === 'upside') {
      const upA = ((a.targetPrice - a.currentPrice) / (a.currentPrice || 1)) || 0;
      const upB = ((b.targetPrice - b.currentPrice) / (b.currentPrice || 1)) || 0;
      return upB - upA;
    } else if (sortMode === 'rsi') {
      return (b.rsi || 0) - (a.rsi || 0);
    } else if (sortMode === 'name') {
      const nameA = (a.name || a.ticker || '').trim();
      const nameB = (b.name || b.ticker || '').trim();
      return nameA.localeCompare(nameB, 'it', { sensitivity: 'base' });
    } else if (sortMode === 'divyield') {
      return (Number(b.dividendYield) || 0) - (Number(a.dividendYield) || 0);
    } else if (sortMode === 'exdiv') {
      const calA = getStockCalendarInfo(a);
      const calB = getStockCalendarInfo(b);
      const hasDivA = Number(a.dividendYield) > 0 && calA && calA.exDivDays !== null && calA.exDivDays !== undefined;
      const hasDivB = Number(b.dividendYield) > 0 && calB && calB.exDivDays !== null && calB.exDivDays !== undefined;
      const daysA = hasDivA ? calA.exDivDays : 999999;
      const daysB = hasDivB ? calB.exDivDays : 999999;
      if (daysA !== daysB) {
        return daysA - daysB;
      }
      return (Number(b.dividendYield) || 0) - (Number(a.dividendYield) || 0);
    }
    return (b.marketCapRaw || 0) - (a.marketCapRaw || 0);
  });

  return filtered;
}

function getFilteredAndSortedStocks() {
  if (state.currentMarket === 'all') {
    const all = [
      ...(MARKET_DATA.it || []),
      ...(MARKET_DATA.eu || []),
      ...(MARKET_DATA.usa || []),
      ...(MARKET_DATA.top || [])
    ];
    return filterAndSortList(all);
  }
  const mktKey = (state.currentMarket === 'usa') ? 'usa' : ((state.currentMarket === 'it') ? 'it' : ((state.currentMarket === 'top') ? 'top' : 'eu'));
  return filterAndSortList(MARKET_DATA[mktKey] || []);
}

