function updateFilterPillsUI() {
  const pModel = document.getElementById('qfModelV7');
  const pCap = document.getElementById('qfCap10B');
  const pDrop1 = document.getElementById('qfDrop1pct');
  const pDiv4 = document.getElementById('qfDiv4');
  const pUnder52 = document.getElementById('qfUnder52w');
  const pCombo = document.getElementById('qfCombo');

  if (pModel) pModel.classList.toggle('active', Boolean(state.isModelV7Active));
  if (pCap) pCap.classList.toggle('active', Boolean(state.isCap10BActive));
  if (pDrop1) pDrop1.classList.toggle('active', Boolean(state.isDrop1PctActive));
  if (pDiv4) pDiv4.classList.toggle('active', state.dividendPriceFilter === 'div4');
  if (pUnder52) pUnder52.classList.toggle('active', state.dividendPriceFilter === 'under52w');
  if (pCombo) pCombo.classList.toggle('active', state.dividendPriceFilter === 'combo');
}

function switchMarketSection(market, scrollIfNeeded = false, fromCarouselSwipe = false) {
  if (state.currentMarket === market) {
    if (!fromCarouselSwipe) centerActiveCarouselTab(market);
    if (scrollIfNeeded) {
      const mainEl = document.querySelector('.main-content');
      if (mainEl) mainEl.scrollIntoView({ behavior: 'smooth', block: 'start' });
    }
    return;
  }

  state.currentMarket = market;

  // Sincronizza tab in alto
  if (elements.tabIT) elements.tabIT.classList.toggle('active', market === 'it');
  if (elements.tabEU) elements.tabEU.classList.toggle('active', market === 'eu');
  if (elements.tabUSA) elements.tabUSA.classList.toggle('active', market === 'usa');
  if (elements.tabTop) elements.tabTop.classList.toggle('active', market === 'top');
  if (elements.tabAll) elements.tabAll.classList.toggle('active', market === 'all');
  if (elements.tabSummary) elements.tabSummary.classList.toggle('active', market === 'summary');

  // Sincronizza indicatori carosello mobile
  document.querySelectorAll('.m-carousel-dot').forEach(dot => {
    dot.classList.toggle('active', dot.getAttribute('data-market') === market);
  });

  // Sincronizza barra fissa in basso
  const bIT = document.getElementById('bottomTabIT');
  const bEU = document.getElementById('bottomTabEU');
  const bUSA = document.getElementById('bottomTabUSA');
  const bTop = document.getElementById('bottomTabTop');
  const bAll = document.getElementById('bottomTabAll');
  const bSum = document.getElementById('bottomTabSummary');
  if (bIT) bIT.classList.toggle('active', market === 'it');
  if (bEU) bEU.classList.toggle('active', market === 'eu');
  if (bUSA) bUSA.classList.toggle('active', market === 'usa');
  if (bTop) bTop.classList.toggle('active', market === 'top');
  if (bAll) bAll.classList.toggle('active', market === 'all');
  if (bSum) bSum.classList.toggle('active', market === 'summary');

  if (!fromCarouselSwipe) {
    centerActiveCarouselTab(market);
  }

  updateMarketHeaderInfo();
  renderStocks();

  // Trigger automatico aggiornamento dati real-time al cambio mercato
  triggerFullMarketRefresh('market_switch');

  if (scrollIfNeeded && window.scrollY > 320) {
    const mainEl = document.querySelector('.main-content');
    if (mainEl) mainEl.scrollIntoView({ behavior: 'smooth', block: 'start' });
  }
}

